import React, { useEffect, useState } from "react";
import { getAllSchemes } from "../services/schemeService";

const SchemePage = () => {

    const [schemes, setSchemes] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchSchemes();
    }, []);

    const fetchSchemes = async () => {
        const data = await getAllSchemes();
        setSchemes(data);
        setLoading(false);
    };

    if (loading) return <h2>Loading schemes...</h2>;

    return (
        <div style={{ padding: "20px" }}>
            <h2>Government Schemes</h2>

            <div style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
                gap: "20px"
            }}>
                {schemes.map((scheme) => (
                    <div key={scheme.id}
                         style={{
                             border: "1px solid #ddd",
                             borderRadius: "10px",
                             overflow: "hidden",
                             boxShadow: "0 4px 10px rgba(0,0,0,0.1)"
                         }}
                    >
                        <img
                            src={scheme.image}
                            alt={scheme.schemeName}
                            style={{
                                width: "100%",
                                height: "180px",
                                objectFit: "cover"
                            }}
                        />

                        <div style={{ padding: "15px" }}>
                            <h3>{scheme.schemeName}</h3>
                            <p><strong>Category:</strong> {scheme.category}</p>
                            <p>{scheme.description.substring(0, 80)}...</p>

                            <a href={scheme.officialLink}
                               target="_blank"
                               rel="noreferrer"
                               style={{
                                   display: "inline-block",
                                   marginTop: "10px",
                                   background: "#28a745",
                                   color: "white",
                                   padding: "8px 12px",
                                   borderRadius: "5px",
                                   textDecoration: "none"
                               }}>
                                Official Website
                            </a>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default SchemePage;
